using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Preliminarily uploads a file to the cloud before sending it in a message, which can be useful for uploading of being recorded voice and video notes.
    /// In all other cases there is no need to preliminary upload a file. Updates updateFile will be used to notify about upload progress.
    /// The upload will not be completed until the file is sent in a message
    /// </summary>
    public Task<TdLib.TdApi.Objects.File> PreliminaryUploadFileAsync(InputFile file = default, FileType fileType = default, int priority = default)
    {

           using var activity =  StartCallActivity("PreliminaryUploadFileAsync", typeof(PreliminaryUploadFile).FullName ?? "PreliminaryUploadFileAsync");

           try
           {
             return client.PreliminaryUploadFileAsync(file, fileType, priority);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
// REUSE-IgnoreEnd